QB.add(23,[{"n":1,"q":"A 45-year-old male presents to the emergency department with severe weakness and palpitations. He has been on a thiazide diuretic for hypertension. His ECG reveals flattened T waves and the presence of U waves. Serum potassium is 2.3 mEq/L. What is the most appropriate initial treatment for this patient?","o":[{"t":"Oral potassium chloride 20 mEq"},{"t":"IV potassium chloride 10 mEq/hour with cardiac monitoring"},{"t":"IV potassium chloride 20 mEq/hour with cardiac monitoring"},{"t":"IV potassium chloride 25 mEq/hour with cardiac monitoring"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) IV potassium chloride 10 mEq/hour with cardiac monitoring"},{"k":"h","l":0,"v":"Explanation :"},{"k":"p","l":0,"v":"For severe hypokalemia (serum potassium of 2.3 mEq/L), IV potassium replacement is necessary, but it should be given cautiously due to the risk of arrhythmias. The standard rate is 10 mEq/hour with cardiac monitoring."},{"k":"p","l":0,"v":"Hypokalemia"},{"k":"b","l":0,"v":"Serum potassium level of 3 to 3.4 mmol/L is classified as mild."},{"k":"b","l":0,"v":"A serum potassium level of 2.5 to 3 mmol/L is classified as moderate."},{"k":"b","l":0,"v":"Serum potassium levels less than 2.5 mmol/L are classified as severe."},{"k":"p","l":0,"v":"Hypokalemia Treatment:"},{"k":"b","l":0,"v":"The therapeutic goals for hypokalemia are to prevent or treat life-threatening complications, correct the potassium deficit, and address the underlying cause."},{"k":"b","l":0,"v":"Potassium replacement is indicated in most hypokalemia cases, especially when renal or gastrointestinal losses are significant."},{"k":"p","l":0,"v":"Mild-to-moderate hypokalemia:"},{"k":"b","l":0,"v":"Typically, it is treated with oral potassium supplements. Providing 60 to 80 mmol/day over days to weeks is usually sufficient."},{"k":"b","l":0,"v":"IV administration is given if oral therapy is not tolerated."},{"k":"p","l":0,"v":"Severe Hypokalemia or hypokalemia with clinical symptoms:"},{"k":"b","l":0,"v":"Replacement therapy must be provided rapidly."},{"k":"b","l":0,"v":"The standard rate is 10 mEq/hour IV administration with cardiac monitoring"},{"k":"b","l":0,"v":"Pain and phlebitis usually occur with peripheral IV infusions when infusion rates exceed 10 mmol/h."},{"k":"b","l":0,"v":"A risk of rebound hyperkalemia exists when rates exceed 20 mmol/h."},{"k":"b","l":0,"v":"Serum potassium levels should be checked every 2 to 4 hours."},{"k":"b","l":0,"v":"In cases of renal or gastrointestinal losses, potassium replacement is aimed at promptly elevating serum potassium levels to a safe range, followed by gradual replenishment of the remaining deficit over days to weeks."}]},{"n":2,"q":"A 68-year-old patient with a history of chronic kidney disease presents in the Emergency Department with palpitations and muscle fasciculations. The ECG shows tall T waves and a prolonged QT interval. Serum electrolytes: Na—136 mEq/l; K—6.2 mEq/l. What is the next immediate step in the management of this patient?","o":[{"t":"IV Insulin"},{"t":"IV Salbutamol"},{"t":"IV Calcium gluconate"},{"t":"Hemodialysis"}],"a":[2],"s":[{"k":"p","l":0,"v":"Correct answer: C) IV Calcium gluconate"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"It is a case of hyperkalemia with ECG changes. The next immediate step is to stabilize the cardiac myocyte membrane with Calcium gluconate ."},{"k":"p","l":0,"v":"Indications of immediate I/V Calcium gluconate administration in hyperkalemia:"},{"k":"b","l":0,"v":"ECG changes of hyperkalemia"},{"k":"b","l":0,"v":"Arrhythmia"},{"k":"b","l":0,"v":"Serum potassium >6.5 mEq/L"}]},{"n":3,"q":"Which of the following is not an ECG finding in hypermagnesemia?","o":[{"t":"Prolonged PR interval"},{"t":"Prolonged QRS interval"},{"t":"Prolonged QT interval"},{"t":"Narrow PR interval"}],"a":[3],"s":[{"k":"h","l":0,"v":"Correct Answer: D) Narrow PR interval"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"The PR interval is prolonged in Hypermagnesemia"},{"k":"p","l":0,"v":"Hypermagnesemia:"},{"k":"p","l":1,"v":"Causes Excessive magnesium intake"},{"k":"p","l":2,"v":"Cathartics, urologic irritants Parenteral magnesium administration Rapid mobilisation from soft tissues Trauma, shock, sepsis Cardiac arrest Burns Impaired magnesium excretion Renal failure Familial hypocalciuric hypercalcemia Others: Adrenal insufficiency Hypothyroidism Hypothermia"},{"k":"p","l":1,"v":"Clinical Findings Vasodilation and neuromuscular blockade"},{"k":"p","l":2,"v":"Hypotension Nausea, lethargy, weakness, respiratory failure, paralysis, and coma Hypoactive tendon reflexes Gastrointestinal hypomotility or ileus Facial flushing Pupillary dilation Paradoxical bradycardia Prolonged PR, QRS, and QT intervals (Options A, B, and C) Heart block and asystole Hypocalcemia and hypercalciuria"},{"k":"p","l":1,"v":"Treatment Identify and interrupt the sources of magnesium"},{"k":"p","l":2,"v":"Magnesium-free cathartics or enemas for ingested magnesium Vigorous IV hydration Hemodialysis Administer IV calcium (100–200 mg over 1–2 h) for temporary improvement"}]},{"n":4,"q":"A 56-year-old male presenting with seizures has a serum magnesium level of 0.5 mmol/L. What is the most likely ECG finding?","o":[{"t":"Tall tented T-wave"},{"t":"ST straightening"},{"t":"Narrow PR interval"},{"t":"Narrow QT interval"}],"a":[1],"s":[{"k":"h","l":0,"v":"Correct Answer: B) ST straightening"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"The scenario is of hypomagnesemia, and ST straightening is an ECG finding."},{"k":"p","l":0,"v":"Hypomagnesemia:"},{"k":"p","l":0,"v":"Plasma magnesium below the reference range of 0.75–1.0 mmol/L (1.5–2.0 mEq/L)."},{"k":"p","l":1,"v":"Clinical Tetany Features Cardiac arrhythmias (e.g., torsades de pointes)"},{"k":"p","l":2,"v":"Central nervous system excitation and seizure Vasoconstriction and hypertension Associated with hyponatremia and hypokalemia ECG abnormalities: prolonged PR or QT intervals (Option C and D ruled out) , T-wave flattening/inversion (Option A ruled out) , ST straightening (Option B)"},{"k":"p","l":1,"v":"Management Identify and treat the underlying cause."},{"k":"p","l":2,"v":"IV magnesium chloride: Administer at a rate of £0.5 mmol/kg in the first 24 hours. IM magnesium sulfate: Alternative if IV access is not possible. Oral magnesium salts: Limited effectiveness due to poor absorption and potential diarrhoea. If caused by diuretic use, potassium-sparing agents can help reduce urinary magnesium loss."}]},{"n":5,"q":"Which of the following will not lead to a plasma magnesium level of < 1.5 mEq/L? Bartter’s syndrome Gitelman’s syndrome Gentamicin Acute pancreatitis Diabetes mellitus Foscarnet therapy Proton pump inhibitor therapy Hungry bone syndrome","o":[{"t":"1,2,3"},{"t":"1,2,3,4,5"},{"t":"3,4,8"},{"t":"None of the above"}],"a":[3],"s":[{"k":"h","l":0,"v":"Correct Answer: D) None of the above"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Hypomagnesemia can be caused by any of the listed issues."},{"k":"p","l":0,"v":"Hypomagnesemia:"},{"k":"p","l":0,"v":"Plasma magnesium below the reference range of 0.75–1.0 mmol/L (1.5–2.0 mEq/L)."},{"k":"p","l":0,"v":"Causes:"},{"k":"p","l":0,"v":"Inadequate Intake Starvation"},{"k":"p","l":2,"v":"Malnutrition Alcoholism Parenteral alimentation"},{"k":"p","l":0,"v":"Gastrointestinal Losses Prolonged vomiting/nasogastric aspiration"},{"k":"p","l":2,"v":"Chronic diarrhoea/laxative abuse Malabsorption Small bowel bypass surgery Fistulae"},{"k":"p","l":0,"v":"Urinary Losses Diuretic therapy"},{"k":"p","l":2,"v":"Alcohol Tubulotoxic drugs ( Gentamicin , Cisplatin) Volume expansion Diabetic ketoacidosis Post-obstructive diuresis Recovery from acute tubular necrosis"},{"k":"p","l":0,"v":"Inherited Tubular Defects Bartter’s syndrome"},{"k":"p","l":2,"v":"Gitelman’s syndrome Primary renal magnesium wasting"},{"k":"p","l":0,"v":"Miscellaneous Acute pancreatitis"},{"k":"p","l":2,"v":"Foscarnet therapy Proton pump inhibitor therapy Hungry bone syndrome Diabetes mellitus"}]},{"n":6,"q":"Which of the following is the normal serum magnesium level?","o":[{"t":"0.7-1 mmol/L"},{"t":"1.5-2 mmol/L"},{"t":"0.3-1.4 mmol/L"},{"t":"1.5-2 mmol/L"}],"a":[0],"s":[{"k":"h","l":0,"v":"Correct Answer: A) 0.7-1 mmol/L"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Normal magnesium level in serum is 0.7-1 mmol/L"},{"k":"p","l":1,"v":"Normal serum magnesium 0.7–1 mmol/L (1.5–2 meq/L; 1.7–2.4 mg/dL)"},{"k":"p","l":1,"v":"Functions of magnesium Crucial for normal neuromuscular activity"},{"k":"p","l":2,"v":"Forms a key complex with ATP for energy metabolism. Acts as a cofactor for enzymes, transporters, and nucleic acids Found in bone, supporting skeletal structure. Within cells, it is involved in biochemical reactions and energy."}]},{"n":7,"q":"Denosumab is a monoclonal antibody used in hypercalcemia. What is its mechanism of action?","o":[{"t":"Increases bone resorption"},{"t":"Binds to RANK receptor"},{"t":"Binds to RANK ligand"},{"t":"Promotes function of osteoclasts"}],"a":[2],"s":[{"k":"h","l":0,"v":"Correct Answer: C) Binds to RANK ligand"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Denosumab binds to the RANK ligand and prevents its binding to the RANK receptor."},{"k":"p","l":0,"v":"Denosumab:"},{"k":"p","l":1,"v":"Definition A monoclonal antibody for the treatment of"},{"k":"p","l":2,"v":"hypercalcemia. It is considered the most powerful antiresorptive agent available."},{"k":"p","l":1,"v":"Mechanism of Binds to RANK ligand (RANKL) (Option B ruled out) Action (Option C) fi prevents its binding to RANK receptor on"},{"k":"p","l":2,"v":"osteoclast precursors and mature osteoclasts fi Inhibits differentiation, activation, and function of osteoclasts (Option D ruled out) fireduces bone resorption (Option A ruled out) and hence reducing bone calcium release into plasma."},{"k":"p","l":1,"v":"Use in malignan Repeated doses of 120 mg subcutaneously for cy hypercalcemia of malignancy (especially in patients"},{"k":"p","l":2,"v":"unresponsive to bisphosphonates). Also used in Osteoporosis"}]},{"n":8,"q":"A 40-year-old female who has been diagnosed with a Parathyroid gland malignancy was brought to ED with acute onset low levels of consciousness and severe pain in the abdomen. Her vitals were HR- 56 bpm, BP- 88/64 mmHg. ECG done showed a shortened QT interval. Serum Ca2+ (calcium)- 13 mg/dL. What is the most appropriate first step in managing this patient?","o":[{"t":"IV fluids"},{"t":"Furosemide"},{"t":"Steroids"},{"t":"IV Zoledronate"}],"a":[0],"s":[{"k":"p","l":0,"v":"Correct answer: A) IV fluids"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"The patient has a Hypercalcemic crisis secondary to Parathyroid malignancy, and the first line of treatment is Adequate hydration with IV Fluids (NS preferred) over the first 24 hours."},{"k":"p","l":0,"v":"Management of Hypercalcemic crisis:"},{"k":"p","l":1,"v":"1) Adequate 4-6 L of IV Normal saline over the first 24 hours and hydration body water must be replenished."},{"k":"p","l":2,"v":"First step in management"},{"k":"p","l":1,"v":"2) Loop diuretics Like Furosemide must be given IV, but only after"},{"k":"p","l":2,"v":"correcting body fluid status (Option B)"},{"k":"p","l":1,"v":"3) Bis- phosphona DOC for hypercalcemic crisis - mainstay of treatment tes (Option D)"},{"k":"p","l":2,"v":"IV Zoledronate 4 mg IM Pamidronate 60 mg The onset of action: 1-3 days (hence not suitable in acute presentations)"},{"k":"p","l":1,"v":"4) Steroids Mainly useful in Malignancy , sarcoidosis , and Vitamin"},{"k":"p","l":2,"v":"D intoxication (Option C)"},{"k":"p","l":1,"v":"5) Others Salmon calcitonin:"},{"k":"p","l":2,"v":"Given as nasal spray Rapid onset of action ADR: Tachyphylaxis Denosumab: Monoclonal antibody against RANK-ligand and prevents its binding to RANK receptor on osteoclasts Gallium nitrate: alternative to Bisphosphonates, ADR- Nephrotoxic Hemodialysis: rarely required"}]},{"n":9,"q":"Which among the following is the least likely cause of this finding seen in the X-ray shown below?","o":[{"t":"Parathyroid hyperplasia"},{"t":"Sarcoidosis"},{"t":"Hungry bone syndrome"},{"t":"Vitamin D intoxication"}],"a":[2],"s":[{"k":"p","l":0,"v":"Correct answer: C) Hungry bone syndrome"},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"X-ray shows Nephrocalcinosis, the deposition of Calcium oxalate and Calcium phosphate in the renal parenchyma secondary to Hypercalcemic states like Primary hyperparathyroidism (Parathyroid hyperplasia), Sarcoidosis, and Vitamin D intoxication."},{"k":"img","v":5588},{"k":"b","l":0,"v":"Hungry bone syndrome , which occurs post-parathyroidectomy, is a cause of Hypocalcemia . Post parathyroidectomy, bone uptake of calcium increases without PTH regulation, leading to hypocalcaemia"},{"k":"b","l":0,"v":"Post parathyroidectomy, bone uptake of calcium increases without PTH regulation, leading to hypocalcaemia"},{"k":"b","l":0,"v":"Post parathyroidectomy, bone uptake of calcium increases without PTH regulation, leading to hypocalcaemia"},{"k":"p","l":0,"v":"Hypercalcemia:"},{"k":"p","l":0,"v":"Causes Primary hyperparathyroidism: Parathyroid hyperplasia/"},{"k":"p","l":2,"v":"adenoma/ malignancy (Option A) Tertiary hyperparathyroidism: secondary to renal insufficiency Hypercalcemia of malignancy: bone tumours, multiple myeloma, breast cancer Granulomatous diseases: Sarcoidosis, tuberculosis, silicosis (Option B) Vitamin D intoxication (Option D) Milk alkali syndrome: excess calcium intake Endocrinal: adrenal insufficiency, pheochromocytoma Drugs: Thiazide diuretics , vitamin A, OCPs"},{"k":"p","l":0,"v":"Clinical features Mild hypercalcemia (11-11.5 mg/dL): usually"},{"k":"p","l":2,"v":"asymptomatic, neuropsychiatric manifestations (lack of concentration, depression, personality changes) Moderate hypercalcemia (11.5-12.5 mg/dL): Nephrolithiasis, peptic ulcer disease, increased risk of fractures"},{"k":"p","l":0,"v":"Severe hypercalcemia (> 12.5 mg/dL): known as Hypercalcemic crisis Gastrointestinal: Pancreatitis Renal: Nephrocalcinosis , AKI/CKD Neurological: Stupor, coma ECG changes: Short QT interval , Bradycardia, AV block"}],"qi":[5588]},{"n":10,"q":"A patient presented to ED with sudden onset breathlessness. Upon examination, you will notice the following signs:  What is the most appropriate definitive management for this patient?","o":[{"t":"IV 10% Calcium gluconate 10 mL"},{"t":"IV Regular insulin infusion at 0.1U/hour"},{"t":"Oral Vitamin D3 1L U daily"},{"t":"IV Sodium bicarbonate (NaHCO3)"}],"a":[0],"s":[{"k":"p","l":0,"v":"Correct answer: A) IV 10% Calcium gluconate 10 mL"},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"Sudden onset breathlessness (due to laryngospasm) with positive Trousseau and Chvostek sign is suggestive of severe Hypocalcemia."},{"k":"img","v":5620},{"k":"b","l":0,"v":"Treatment of choice in severe Hypocalcemia is IV Calcium Gluconate 10% 10 mL."},{"k":"p","l":0,"v":"Hypocalcemia:"},{"k":"p","l":1,"v":"Clinical Paraesthesia - usually involving fingers and toes features Circumoral numbness"},{"k":"p","l":2,"v":"Positive Chvostek sign : twitching of circumoral muscles on gentle tapping of the facial nerve Positive Trousseau sign : Carpal spasm is seen upon inflating the BP cuff to 20 mmHg above the patient’s SBP for 3 mins. Severe: Carpopedal spasm, Laryngospasm, Bronchospasm, QT prolongation on ECG"},{"k":"p","l":1,"v":"Management Acute Hypocalcemia/Severe symptoms: IV 10%"},{"k":"p","l":2,"v":"Calcium Gluconate 10 mL diluted with 5% Dextrose/ Normal saline (Option A) Chronic Hypocalcemia: Oral Calcium tablet 1000-1500 mg/day (elemental calcium) + Oral Vitamin D3 25K-1L U/day (Option C)"}],"qi":[5591]},{"n":11,"q":"A patient’s serum Calcium (Ca2+) value was 8 mg/dL. Which among the following is the least likely explanation for this?","o":[{"t":"Milk alkali syndrome"},{"t":"Elderly female with osteomalacia"},{"t":"Post Parathyroid gland resection"},{"t":"Baby detected with microdeletion on Chromosome 22q11"}],"a":[0],"s":[{"k":"p","l":0,"v":"Correct answer: A) Milk alkali syndrome"},{"k":"p","l":0,"v":"Milk alkali syndrome causes Hypercalcemia (NOT Hypo)."},{"k":"p","l":0,"v":"Calcium normal value: 8.5-10.5 mg%"},{"k":"p","l":0,"v":"Causes of Hypocalcemia:"},{"k":"p","l":1,"v":"Low PTH levels Parathyroid agenesis"},{"k":"p","l":2,"v":"Post-Parathyroidectomy (Hungry bone syndrome) Post-radiation (Radiotherapy for neck malignancies)"},{"k":"p","l":1,"v":"High PTH levels Vitamin D deficiency (nutritional/renal cause)"},{"k":"p","l":2,"v":"Pseudohypoparathyroidism syndrome (G protein mutations)"},{"k":"p","l":1,"v":"Drugs Ca2+ chelators"},{"k":"p","l":2,"v":"Bisphosphonates Phenytoin Ketoconazole"},{"k":"p","l":1,"v":"Miscellaneous/others Acute pancreatitis"},{"k":"p","l":2,"v":"Rhabdomyolysis Osteoblastic metastases (Prostate cancer)"},{"k":"p","l":0,"v":"Elderly female with osteomalacia (Option B) : Suggestive of Vitamin D deficiency"},{"k":"p","l":0,"v":"Post parathyroid gland resection (Option C) : Post-parathyroidectomy - PTH levels fall."},{"k":"p","l":0,"v":"Baby detected with microdeletion on Chromosome 22q11 (Option D) : Diagnostic of DiGeorge syndrome - defect of 3rd and 4th branchial arch causing thymus and parathyroid gland hypoplasia."},{"k":"p","l":0,"v":"All of these are causes of hypocalcemia ."}]},{"n":12,"q":"All of the following drugs help in the elimination of Potassium (K+) from the body except","o":[{"t":"Calcium gluconate"},{"t":"Patiromer"},{"t":"Sodium polystyrene sulfonate"},{"t":"Furosemide"}],"a":[0],"s":[{"k":"p","l":0,"v":"Correct answer: A) Calcium gluconate"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Calcium gluconate antagonizes the cardiac effects of hyperkalemia by raising the action potential threshold, thereby reducing cardiac excitability and not by helping in the elimination of K+."},{"k":"p","l":0,"v":"Drugs used in Hyperkalemia:"},{"k":"p","l":1,"v":"Immediate antagonism of cardiac Calcium gluconate: (Option A) effects Dose: 10 mL of 10% IV Calcium gluconate"},{"k":"p","l":2,"v":"DOC in management of Acute severe hyperkalemia (K+ > 6.5 mEq/L) DOC in Hyperkalemia with ECG changes"},{"k":"p","l":1,"v":"Redistribution of plasma K+ Regular Insulin:"},{"k":"p","l":2,"v":"10 U of IV Regular insulin Usually followed by 50 mL 50% Dextrose Most effective drug"},{"k":"p","l":1,"v":"Removal of K+ Sodium polystyrene sulfonate: ADR - Intestinal necrosis"},{"k":"p","l":2,"v":"(Option C) Sodium zirconate (ZS-9): more safer Patiromer: Oral novel potassium binder (Option B) Loop & Thiazide diuretics: Furosemide, Hydrochlorothiazide (Option D) Hemodialysis: Most effective for K+ elimination, done for refractory hyperkalemia. Sodium bicarbonate (NaHCO3) & IV Normal saline"}]},{"n":13,"q":"A 55-year-old female with a history of congestive heart failure on ACE inhibitors presents to the emergency department with symptoms of weakness and palpitations. On examination, there were signs of elevated JVP and bounding pulse. The ECG findings of the patient suggest tall T waves and wide QRS complex. What is the most appropriate treatment option for this patient?","o":[{"t":"IV Albuterol"},{"t":"IV Epinephrine"},{"t":"10 units of Regular Insulin"},{"t":"IV Furosemide"}],"a":[3],"s":[{"k":"p","l":0,"v":"Correct answer: D) IV Furosemide"},{"k":"h","l":0,"v":"Explanation :"},{"k":"p","l":0,"v":"The following symptoms and signs in the patient"},{"k":"p","l":0,"v":"(Elevated JVP and bounding pulse) and ECG findings showing tall T waves and a wide QRS complex suggest Hyperkalemia in hypervolemic patients with preserved kidney function."},{"k":"b","l":0,"v":"CHF leads to volume retention, and since the patient is on ACE inhibitors, hyperkalemia has occurred"},{"k":"p","l":0,"v":"Hyperkalemia:"},{"k":"b","l":0,"v":"Usually greater than 5.0 mEq/L to 5.5 mEq/L."},{"k":"b","l":0,"v":"While mild hyperkalemia is usually asymptomatic, high potassium levels may cause life-threatening cardiac arrhythmias, muscle weakness, or paralysis."},{"k":"b","l":0,"v":"Symptoms usually develop at higher levels, 6.5 mEq/L to 7 mEq/L."},{"k":"p","l":0,"v":"Diagnosis :"},{"k":"p","l":0,"v":"The first test that should be ordered in a patient with suspected hyperkalemia is an ECG since the most lethal complication of hyperkalemia is cardiac conduction abnormalities, which can lead to cardiac arrest and death."},{"k":"p","l":0,"v":"Elevated potassium causes ECG changes in a dose-dependent manner :"},{"k":"b","l":0,"v":"K = 5.5 to 6.5 mEq/L ECG will show tall, peaked t-waves"},{"k":"b","l":0,"v":"K = 6.5 to 7.5 mEq/L ECG will show loss of p-waves"},{"k":"b","l":0,"v":"K = 7 to 8 ECG mEq/L will show a widening of the QRS complex"},{"k":"b","l":0,"v":"K = 8 to 10 mEq/L will produce cardiac arrhythmias, sine wave pattern, and asystole"},{"k":"p","l":0,"v":"ECG features of hyperkalemia :"},{"k":"b","l":0,"v":"Small or absent P wave"},{"k":"b","l":0,"v":"Prolonged PR interval"},{"k":"b","l":0,"v":"Augmented R wave"},{"k":"b","l":0,"v":"Wide QRS"},{"k":"b","l":0,"v":"Peaked T waves"},{"k":"p","l":0,"v":"Serum blood urea nitrogen and creatinine are used to assess renal function, and urinalysis is used to screen for renal disease."},{"k":"p","l":0,"v":"Urine potassium, sodium, and osmolality may also help evaluate the cause."},{"k":"p","l":0,"v":"Uric acid and phosphorus should be ordered in patients with suspected tumour lysis syndrome."},{"k":"p","l":0,"v":"Treatment:"},{"k":"b","l":0,"v":"Exogenous sources of potassium should be immediately discontinued."},{"k":"b","l":0,"v":"Calcium therapy will stabilize the cardiac response to hyperkalemia and is a first-line therapy in hyperkalemia-related arrhythmias and ECG changes."},{"k":"b","l":0,"v":"Calcium should never be given in bicarbonate-containing fluids, as it can cause the precipitation of calcium carbonate."},{"k":"b","l":0,"v":"Insulin will drive the potassium back into the cell and lowering serum potassium levels. The common regimen is ten units of regular insulin given with 50 ml of a 50% dextrose solution (D50)."},{"k":"b","l":0,"v":"Beta-2 adrenergics such as albuterol will also shift potassium intracellularly and reduce serum potassium levels."},{"k":"b","l":0,"v":"Intravenous epinephrine , however, should not be used to manage hyperkalemia due to an increased risk of causing angina ."},{"k":"b","l":0,"v":"Loop or thiazide diuretics may help enhance potassium excretion."},{"k":"b","l":0,"v":"In hypervolemic patients with preserved kidney function (patients with congestive cardiac failure), 40 mg of intravenous furosemide is administered every 12 hours."},{"k":"b","l":0,"v":"In euvolemic or hypovolemic patients with preserved kidney function, an isotonic saline infusion is given."},{"k":"b","l":0,"v":"Haemodialysis should be preferred in patients with end-stage renal disease."},{"k":"p","l":0,"v":"IV Albuterol (Option A): Helps shift potassium intracellularly, but it is usually considered an adjunctive treatment rather than a primary approach in hypervolemic patients."},{"k":"p","l":0,"v":"IV Epinephrine (Option B): Not typically used for the management of hyperkalemia and may not be appropriate for this patient’s situation."},{"k":"p","l":0,"v":"10 units of Regular Insulin (Option C): Effective for lowering serum potassium levels, but without the administration of glucose to prevent hypoglycemia and in the context of hypervolemia, it is less suitable as a standalone treatment in this scenario."}]},{"n":14,"q":"Which of the following is not a cause of hyperkalemia?","o":[{"t":"Succinylcholine medication"},{"t":"Tumor lysis syndrome"},{"t":"Metabolic acidosis"},{"t":"Hyperaldosteronism"}],"a":[3],"s":[{"k":"p","l":0,"v":"Correct answer: D) Hyperaldosteronism"},{"k":"h","l":0,"v":"Explanation :"},{"k":"p","l":0,"v":"Hyperaldosteronism is associated with hypokalemia, not hyperkalemia. Aldosterone increases potassium excretion by the kidneys, leading to low potassium levels."},{"k":"p","l":0,"v":"Hyperkalemia:"},{"k":"b","l":0,"v":"Usually greater than 5.0 mEq/L to 5.5 mEq/L."},{"k":"b","l":0,"v":"While mild hyperkalemia is usually asymptomatic, high potassium levels may cause life-threatening cardiac arrhythmias, muscle weakness, or paralysis."},{"k":"b","l":0,"v":"Symptoms usually develop at higher levels, 6.5 mEq/L to 7 mEq/L."},{"k":"p","l":0,"v":"Causes:"},{"k":"b","l":0,"v":"Pseudohyperkalemia is most commonly due to hemolysis of the sample, causing intracellular potassium to be measured in the serum."},{"k":"p","l":1,"v":"Increased Potassium Increased potassium intake from food is a very Intake uncommon cause of hyperkalemia in adult patients with"},{"k":"p","l":2,"v":"normal renal function but can be an important cause in those with kidney disease."},{"k":"p","l":1,"v":"Intracellular Cellular injury Potassium Shifts Metabolic acidosis (Option C)"},{"k":"p","l":2,"v":"Sepsis Dehydration Insulin deficiency Diabetic Ketoacidosis Tumor lysis syndrome (Option B) Hyperkalemic periodic paralysis Medications such as Succinylcholine (Option A)"},{"k":"p","l":1,"v":"Impaired Potassium Acute or chronic kidney disease is a common cause of Excretion hyperkalemia."},{"k":"p","l":2,"v":"Hyperkalemia is usually not seen until the glomerular filtration rate falls below 30 ml/min. Tubular dysfunction due to aldosterone deficiency."}]},{"n":15,"q":"A 45-year-old male with Acute myeloid leukaemia is admitted for chemotherapy. On the third day of treatment, he complains of muscle weakness and palpitations. Serum uric acid levels are elevated. On examination, there is a sign of hypoperfusion, and his ECG shows peaked T waves. What is the most likely cause of his presentation?","o":[{"t":"Hypoaldosteronism"},{"t":"Tumor lysis syndrome"},{"t":"Gout"},{"t":"Drug reactions"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) Tumor lysis syndrome"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Tumor Lysis Syndrome occurs when large numbers of cancer cells are destroyed rapidly, typically after chemotherapy or radiation therapy. The rapid cell death causes the release of intracellular contents into the bloodstream."},{"k":"b","l":0,"v":"TLS typically occurs within 1-5 days after chemotherapy"},{"k":"p","l":0,"v":"Electrolyte Imbalances in TLS:"},{"k":"b","l":0,"v":"Hyperkalemia : From the release of intracellular potassium from the cytoplasm. This leads to peaked T waves on ECG, arrhythmias , and muscle weakness ."},{"k":"b","l":0,"v":"This leads to peaked T waves on ECG, arrhythmias , and muscle weakness ."},{"k":"b","l":0,"v":"This leads to peaked T waves on ECG, arrhythmias , and muscle weakness ."},{"k":"b","l":0,"v":"Hyperphosphatemia : The release of phosphate from the nucleus and cytoplasm, which can lead to hypocalcemia (because calcium binds to phosphate)."},{"k":"b","l":0,"v":"Hyperuricemia : Due to the breakdown of purines (from Nucleic acids), leading to uric acid buildup . This can precipitate in the kidneys and lead to acute kidney injury ."},{"k":"b","l":0,"v":"This can precipitate in the kidneys and lead to acute kidney injury ."},{"k":"b","l":0,"v":"This can precipitate in the kidneys and lead to acute kidney injury ."},{"k":"b","l":0,"v":"Hypocalcemia : Occurs as a result of phosphate binding to calcium, leading to a drop in serum calcium levels, which can cause muscle cramps , tetany , or seizures."},{"k":"p","l":0,"v":"Management :"},{"k":"b","l":0,"v":"TLS is managed by hydration , allopurinol (to prevent uric acid buildup), and, if necessary, rasburicase (to break down uric acid), as well as treatment for electrolyte abnormalities."},{"k":"p","l":0,"v":"Hypoaldosteronism (Option A) : Causes hyperkalemia and hyponatremia but does not explain the elevated uric acid or the acute systemic symptoms seen in this patient."},{"k":"p","l":0,"v":"Gout (Option C): Elevated uric acid is common, but gout presents with joint pain and inflammation, not acute electrolyte imbalances and ECG changes."},{"k":"p","l":0,"v":"Drug reactions (Option D) : While chemotherapy drugs can cause electrolyte disturbances, the specific pattern of findings (elevated uric acid and peaked T waves) points to tumour lysis syndrome, not a nonspecific drug reaction."}]},{"n":16,"q":"A 65-year-old male is brought to the emergency department with vomiting and seizures. What is his most probable serum sodium level?","o":[{"t":"132"},{"t":"127"},{"t":"120"},{"t":"135"}],"a":[2],"s":[{"k":"h","l":0,"v":"Correct Answer: C) 120"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"The scenario is of severe hyponatremia, i.e., Na level <124 , since he is presenting with vomiting and seizures, which will not be present in mild and moderate hyponatremia."},{"k":"p","l":0,"v":"Hyponatremia- a serum Na < 135 mmol/L:"},{"k":"p","l":1,"v":"Severity Serum Sodium Level (mmol/L) Symptoms"},{"k":"p","l":1,"v":"Mild 130–135 None"},{"k":"p","l":2,"v":"(Option A ruled out) (Option D ruled out)"},{"k":"p","l":1,"v":"Moderate 125–129 Nausea, Delirium, Headache"},{"k":"p","l":2,"v":"(Option B ruled out)"},{"k":"p","l":1,"v":"Severity Serum Sodium Level (mmol/L) Symptoms"},{"k":"p","l":1,"v":"Severe < 124 Vomiting , Somnolence, Seizures ,"},{"k":"p","l":2,"v":"(Option C) Coma, Cardiorespiratory arrest"}]},{"n":17,"q":"A 65-year-old female presents to the clinic with complaints of muscle weakness, fatigue, and occasional palpitations for the past few days. She has a history of congestive heart failure and is on furosemide for fluid management. On physical examination, she appears mildly dehydrated. ECG findings are given below. What is the most likely electrolyte abnormality in this patient?","o":[{"t":"Hyperkalemia"},{"t":"Hyponatremia"},{"t":"Hypokalemia"},{"t":"Hypernatremia"}],"a":[2],"s":[{"k":"h","l":0,"v":"Correct Answer: C) Hypokalemia"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"The patient's symptoms, including muscle weakness, fatigue, and the ECG findings (flattened T waves and U waves) , are indicative of hypokalemia ."},{"k":"p","l":0,"v":"Hypokalemia"},{"k":"b","l":0,"v":"Serum potassium level of 3 to 3.4 mmol/L is classified as mild."},{"k":"b","l":0,"v":"A serum potassium level of 2.5 to 3 mmol/L is classified as moderate."},{"k":"b","l":0,"v":"Serum potassium levels less than 2.5 mmol/L are classified as severe."},{"k":"p","l":0,"v":"Clinical features:"},{"k":"b","l":0,"v":"Symptoms indicative of potassium deficiency include muscle weakness, cramps, spasms, fatigue, palpitations, constipation, and abdominal discomfort."},{"k":"b","l":0,"v":"It can also present with torsades de pointes and ventricular tachycardia."},{"k":"b","l":0,"v":"Clinical symptoms of hypokalemia are present when the serum potassium level is less than 3 mmol/L."},{"k":"b","l":0,"v":"Significant muscle weakness occurs at serum potassium levels below 2.5 mmol/L but can occur at higher levels if the onset is acute."},{"k":"p","l":0,"v":"Death in hypokalemia:"},{"k":"b","l":0,"v":"Hypokalemia manifests as an ascending paralysis, with the lower extremities developing profound weakness before the trunk and upper extremities."},{"k":"b","l":0,"v":"The condition may affect the respiratory muscles, which can lead to respiratory failure and death."},{"k":"p","l":0,"v":"Diagnosis :"},{"k":"b","l":0,"v":"Serum electrolytes can help assess hypokalemia severity and detect other electrolyte deficiencies."},{"k":"b","l":0,"v":"Urinary potassium excretion assessment: Distinguish renal losses from other causes. Excretion of more than 30 mEq of potassium per day indicates inappropriate renal potassium loss."},{"k":"b","l":0,"v":"Spot urine potassium concentration or urine potassium-to-creatinine ratio: Urine potassium concentration greater than 15 or a ratio greater than 13 mEq/mmol of creatinine."},{"k":"p","l":0,"v":"ECG findings:"},{"k":"b","l":0,"v":"Decreased T wave amplitude (Earliest ECG change)"},{"k":"b","l":0,"v":"Depressed ST segment"},{"k":"b","l":0,"v":"Appearance of a U-wave"},{"k":"b","l":0,"v":"Prolonged QT interval"},{"k":"b","l":0,"v":"T-wave flattening initially manifests, followed by T-wave inversion and eventually the absence of T wave."},{"k":"p","l":0,"v":"CT and MRI imaging: These tests may help detect structural abnormalities causing hypokalemia or evaluate concomitant conditions."},{"k":"p","l":0,"v":"Hyperkalemia (Option A): Typically causes peaked T waves and can result in muscle weakness or paralysis, which is not consistent with her ECG findings or clinical picture."},{"k":"p","l":0,"v":"Hyponatremia (Option B): Usually presents with confusion, nausea, or seizures, which are absent in this case."},{"k":"p","l":0,"v":"Hypernatremia (Option D): Would present with dehydration and neurological symptoms, but there are no indications of such an issue here."}],"qi":[5599]},{"n":18,"q":"A 40-year-old male presents to the clinic with muscle weakness, fatigue and occasional palpitations. Laboratory tests reveal serum potassium levels of 2.9 mEq/L. Which of the following syndromes is not a known cause of this condition?","o":[{"t":"Liddle syndrome"},{"t":"Gitelman syndrome"},{"t":"Fanconi syndrome"},{"t":"Kounis syndrome"}],"a":[3],"s":[{"k":"h","l":0,"v":"Correct Answer: D) Kounis syndrome"},{"k":"h","l":0,"v":"Explanation :"},{"k":"p","l":0,"v":"Kounis syndrome :"},{"k":"b","l":0,"v":"A condition characterised by the occurrence of acute coronary syndrome associated with an allergic reaction/anaphylaxis."},{"k":"b","l":0,"v":"Mast cell activation and release of cytokines lead to coronary artery spasm or plaque rupture."},{"k":"b","l":0,"v":"It is unrelated to potassium levels and, therefore, is not a cause of hypokalemia."},{"k":"p","l":0,"v":"Normal Serum potassium levels = 3.5-5 meq/L"},{"k":"p","l":0,"v":"Hypokalemia : Defined as a serum potassium level of less than 3.5 mEq/L."},{"k":"b","l":0,"v":"Potassium is an essential electrolyte critical in various physiological functions, including muscle contraction, nerve transmission, and maintaining normal cardiac rhythm."},{"k":"b","l":0,"v":"Hypokalemia can lead to symptoms such as muscle weakness, cramping, fatigue, and arrhythmias."},{"k":"p","l":0,"v":"Causes of Hypokalemia:"},{"k":"p","l":0,"v":"Hypokalemia can result from various mechanisms, including decreased intake, increased loss, or potassium shifts into cells. Here are the main categories of causes:"},{"k":"p","l":0,"v":"Increased Renal Loss Diuretic Use: Loop diuretics (furosemide) and thiazide"},{"k":"p","l":2,"v":"diuretics can lead to significant potassium loss. Hyperaldosteronism : Conditions like Conn's syndrome increase aldosterone secretion, increasing potassium excretion."},{"k":"p","l":0,"v":"Renal Tubular Disorders Gitelman syndrome (Option B) : A genetic disorder"},{"k":"p","l":2,"v":"causing loss of electrolytes, including potassium. Liddle syndrome (Option A) : A genetic condition that increases sodium reabsorption and potassium excretion. Cushing’s Syndrome : Excess cortisol can lead to hypokalemia through its mineralocorticoid effects."},{"k":"p","l":0,"v":"Gastrointestinal Losses Vomiting"},{"k":"p","l":2,"v":"Diarrhea Laxative Abuse"},{"k":"p","l":0,"v":"Decreased potassium Intake Inadequate Dietary Intake"},{"k":"p","l":2,"v":"Intravenous Fluids: Administration of IV fluids without adequate potassium supplementation can lead to hypokalemia, particularly in hospitalised patients."},{"k":"p","l":0,"v":"Cellular Shift Alkalosis : In metabolic alkalosis, potassium shifts into"},{"k":"p","l":2,"v":"cells, contributing to hypokalemia. Insulin Administration: Insulin promotes potassium uptake into cells, which can lead to hypokalemia, especially when given in high doses."},{"k":"p","l":0,"v":"Miscellaneous Causes Fanconi Syndrome (Option C) : A condition that affects"},{"k":"p","l":2,"v":"the PCT and can lead to the loss of potassium and other electrolytes. Magnesium Deficiency"},{"k":"p","l":0,"v":"Increased Renal Loss Diuretic Use: Loop diuretics (furosemide) and thiazide"},{"k":"p","l":2,"v":"diuretics can lead to significant potassium loss. Hyperaldosteronism : Conditions like Conn's syndrome increase aldosterone secretion, increasing potassium excretion."},{"k":"p","l":0,"v":"Renal hypokalemia includes Congenital adrenal hyperplasia from 11-b or chloride-responsive metabolic alkalosis 17-a-hydroxylase deficiency"},{"k":"p","l":2,"v":"Renin-secreting tumors Ectopic corticotropin stimulation ectopic adrenocorticotropic hormone syndrome Cushing disease or Cushing syndrome Hereditary glucocorticoid-responsive aldosteronism Hypertensive emergency and malignant hypertension Renovascular hypertension renal artery stenosis"},{"k":"img","v":5632}]},{"n":19,"q":"A 55-year-old female with a history of chronic kidney disease presents to the emergency department with muscle weakness and palpitations. What is the most likely acid-base disturbance, given the patient's serum potassium and bicarbonate levels? Laboratory results reveal the following: Serum potassium: 6.5 mEq/L Serum bicarbonate: 15 mEq/L","o":[{"t":"Metabolic alkalosis"},{"t":"Metabolic acidosis"},{"t":"Respiratory alkalosis"},{"t":"Respiratory acidosis"}],"a":[1],"s":[{"k":"h","l":0,"v":"Correct Answer: B) Metabolic acidosis"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Serum potassium: 6.5 mEq/L (normal range: 3.5-5.0 mEq/L)"},{"k":"p","l":0,"v":"Serum bicarbonate: 15 mEq/L (normal range: 22-24 mEq/L)"},{"k":"b","l":0,"v":"The patient has hyperkalemia (high potassium level), which can occur in conditions of metabolic acidosis, particularly in kidney disease, where potassium excretion is impaired."},{"k":"b","l":0,"v":"The patient’s bicarbonate level of 15 mEq/L indicates metabolic acidosis, which is below the normal range."},{"k":"b","l":0,"v":"The combination of hyperkalemia and low bicarbonate strongly suggests a diagnosis of metabolic acidosis."},{"k":"p","l":0,"v":"Serum potassium"},{"k":"b","l":0,"v":"Normal serum potassium levels typically range from 3.5 to 5.0 mEq/L."},{"k":"p","l":0,"v":"Potassium is crucial for various physiological functions, including:"},{"k":"b","l":0,"v":"Maintaining normal cellular function."},{"k":"b","l":0,"v":"Regulating nerve conduction and muscle contraction, including the heart."},{"k":"b","l":0,"v":"Maintaining acid-base balance."},{"k":"p","l":0,"v":"Relationship of Serum potassium with insulin and pH"},{"k":"b","l":0,"v":"Insulin fl Serum Potassium: Insulin promotes potassium uptake into cells, lowering serum potassium levels."},{"k":"b","l":0,"v":"PH is inversely proportional to serum potassium."},{"k":"b","l":0,"v":"Acidosis › Serum Potassium: In metabolic acidosis, potassium shifts out of cells to compensate for elevated plasma H+ ions in acidosis, which shift inside the cells, resulting in elevated serum potassium levels."},{"k":"b","l":0,"v":"Alkalosis fl Serum Potassium: In metabolic alkalosis, potassium shifts into cells to compensate for H+ ions, which shift outside the cells into plasma in alkalosis to maintain electrolyte balance, potentially leading to lower serum potassium levels."},{"k":"p","l":0,"v":"Hyperkalemia (Elevated Potassium Levels): Defined as serum potassium greater than 5.0 mEq/L."},{"k":"p","l":0,"v":"Common causes include:"},{"k":"b","l":0,"v":"Chronic kidney disease: Impaired excretion."},{"k":"b","l":0,"v":"Acute kidney injury: Sudden loss of kidney function."},{"k":"b","l":0,"v":"Medications : ACE inhibitors, potassium-sparing diuretics."},{"k":"b","l":0,"v":"Acidosis : Metabolic acidosis can cause potassium to shift from cells to the extracellular space."},{"k":"b","l":0,"v":"Symptoms may include muscle weakness, fatigue, palpitations, and, in severe cases, cardiac arrest."},{"k":"p","l":0,"v":"Treatment :"},{"k":"b","l":0,"v":"Calcium gluconate or calcium chloride (for cardiac protection)."},{"k":"b","l":0,"v":"Insulin and glucose (to shift potassium back into cells)."},{"k":"b","l":0,"v":"Beta-agonists"},{"k":"p","l":0,"v":"Hypokalemia (Low Potassium Levels): Defined as serum potassium less than 3.5 mEq/L."},{"k":"b","l":0,"v":"Diuretics : Particularly loop and thiazide diuretics."},{"k":"b","l":0,"v":"Gastrointestinal losses: Vomiting, diarrhea, or excessive laxative use."},{"k":"b","l":0,"v":"Hyperaldosteronism : Increased potassium secretion."},{"k":"b","l":0,"v":"Symptoms may include muscle weakness, cramping, fatigue, and arrhythmias."},{"k":"b","l":0,"v":"Oral or intravenous potassium replacement."},{"k":"b","l":0,"v":"Addressing underlying causes ( adjusting diuretics, treating vomiting/diarrhea)."}]},{"n":20,"q":"A 65-year-old female is admitted to the hospital with severe dehydration and a serum sodium level of 160 mEq/L. You plan to correct her sodium levels gradually to prevent complications such as cerebral oedema. The goal is to decrease the serum sodium level by no more than how many mEq per hour.","o":[{"t":"1.5 mEq per hour"},{"t":"0.5 mEq per hour"},{"t":"2 mEq per hour"},{"t":"1 mEq per hour"}],"a":[1],"s":[{"k":"h","l":0,"v":"Correct Answer: B) 0.5 mEq per hour"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"To safely correct hypernatremia, the sodium reduction should not exceed 0.5 mEq/L per hour to minimise the risk of cerebral oedema."},{"k":"b","l":0,"v":"The primary goal in treating hypernatremia is to lower serum sodium gradually to avoid rapid shifts in water into brain cells, which can cause cerebral oedema."},{"k":"b","l":0,"v":"The recommended rate of correction for chronic hypernatremia is no more than 0.5 mEq/L per hour or 12 mEq/L per day."},{"k":"b","l":0,"v":"Proper management of hypernatremia involves identifying the underlying condition and correcting the hypertonicity."},{"k":"b","l":0,"v":"The goal of therapy is to correct both the serum sodium and the intravascular volume."},{"k":"b","l":0,"v":"In patients with severe dehydration or shock, the initial step is fluid resuscitation with isotonic fluids before free water correction."},{"k":"p","l":0,"v":"Hypernatremia is corrected by calculating the free water deficit using the formula:"},{"k":"b","l":0,"v":"Total Body Water[0.6 in men and 0.5 in women x body weight(kg)] x [(plasma sodium/140) -1]"},{"k":"b","l":0,"v":"4ml x bodyweight x (desired change in serum sodium meq/L)"},{"k":"b","l":0,"v":"Correcting too quickly ( e.g.>1 mEq/L per hour ) can result in serious complications like brain swelling."},{"k":"b","l":0,"v":"Close serial monitoring of serum sodium every 2 to 4 hours is essential during the acute phase of correction."},{"k":"b","l":0,"v":"The estimated free water deficit should be corrected over 48 to 72 hours."}]},{"n":21,"q":"A 70-year-old male presents to the hospital with confusion and dehydration. Blood tests reveal a serum sodium level of 150 mEq/L. Which of the following is not a cause of this condition?","o":[{"t":"Diabetes insipidus"},{"t":"Excessive lactulose use"},{"t":"Alzheimer’s disease"},{"t":"Hypoaldosteronism"}],"a":[3],"s":[{"k":"h","l":0,"v":"Correct Answer: D) Hypoaldosteronism"},{"k":"h","l":0,"v":"Explanation :"},{"k":"p","l":0,"v":"Hypoaldosteronism leads to hyponatremia , as aldosterone is responsible for sodium retention in the kidneys. A deficiency would result in sodium loss."},{"k":"p","l":0,"v":"Hypernatremia is defined as a serum sodium concentration of greater than 145 meq/L."},{"k":"p","l":0,"v":"Causes of Hypernatremia can be broadly classified into two categories: Water deficit and excess solute."},{"k":"p","l":1,"v":"Water Deficit (Dehydration) Diabetes Insipidus (Central or Nephrogenic) (Option A) :"},{"k":"p","l":2,"v":"Inadequate secretion or response to antidiuretic hormone (ADH) leads to excessive free water loss in the urine. Gastrointestinal Losses: Severe diarrhoea, especially in conditions like osmotic diarrhoea can cause loss of water leading to hypernatremia. Burns : Large surface area burns can lead to fluid loss and concentration of sodium. Impaired Thirst Mechanism (Option C) : This can occur in elderly patients with neurological conditions (dementia, Alzheimer’s disease). Excessive lactulose use (Option B) : Lactulose can cause dehydration and hypernatremia through significant fluid losses, especially in patients with diarrhoea."},{"k":"p","l":1,"v":"Excess Sodium Gain Hypertonic Sodium Solutions: Administration of"},{"k":"p","l":2,"v":"hypertonic saline (e.g., 3% saline) or sodium bicarbonate can cause hypernatremia. Primary Hyperaldosteronism (Conn’s Syndrome): Excess aldosterone causes sodium retention and potassium excretion, potentially leading to hypernatremia in rare cases."},{"k":"p","l":1,"v":"Water Deficit (Dehydration) Diabetes Insipidus (Central or Nephrogenic) (Option A) :"},{"k":"p","l":2,"v":"Inadequate secretion or response to antidiuretic hormone (ADH) leads to excessive free water loss in the urine. Gastrointestinal Losses: Severe diarrhoea, especially in conditions like osmotic diarrhoea can cause loss of water leading to hypernatremia. Burns : Large surface area burns can lead to fluid loss and concentration of sodium. Impaired Thirst Mechanism (Option C) : This can occur in elderly patients with neurological conditions (dementia, Alzheimer’s disease). Excessive lactulose use (Option B) : Lactulose can cause dehydration and hypernatremia through significant fluid losses, especially in patients with diarrhoea."},{"k":"p","l":1,"v":"Iatrogenic (Hospital-Acquir Inappropriate Use of Diuretics: Certain diuretics can ed) Causes cause free water loss without significant sodium loss."},{"k":"p","l":2,"v":"Overcorrection of Hyponatremia: Too rapid correction of hyponatremia with hypertonic saline can result in hypernatremia."},{"k":"p","l":0,"v":"Common Conditions Associated with Hypernatremia:"},{"k":"b","l":0,"v":"Diabetes Insipidus (central or nephrogenic)"},{"k":"b","l":0,"v":"Severe dehydration (diarrhoea, vomiting, burns, sweating)"},{"k":"b","l":0,"v":"Excessive salt intake or administration of hypertonic saline"},{"k":"b","l":0,"v":"Osmotic diuresis (e.g., in hyperglycemia)"}]},{"n":22,"q":"A 60-year-old male weighing 60 kg is admitted to the emergency department with symptoms of confusion and seizures. Blood investigations revealed a serum sodium level of 125 mEq/L. You aim to calculate the total sodium deficit that needs to be corrected to bring his serum sodium to a target of 135 mEq/L. What is the total sodium deficit (in mEq) that needs to be corrected in this patient?","o":[{"t":"180 mEq"},{"t":"240 mEq"},{"t":"360 mEq"},{"t":"216 mEq"}],"a":[2],"s":[{"k":"h","l":0,"v":"Correct Answer: C) 360 mEq"},{"k":"h","l":0,"v":"Explanation"},{"k":"p","l":0,"v":"Hyponatremia is defined as a serum sodium concentration of less than 135 mEq/L but can vary to some extent depending upon the set values of varied laboratories."},{"k":"p","l":0,"v":"Sodium Deficit Formula: Sodium deficit = (Desired Nan - Actual Nan) × Total Body Water (TBW)"},{"k":"p","l":0,"v":"Total Body Water (TBW):"},{"k":"p","l":0,"v":"TBW = 0.6 × Body Weight(for males)"},{"k":"p","l":0,"v":"= 0.5 x Body Weight(for females)"},{"k":"p","l":0,"v":"TBW for this patient: 0.6 × 60 kg = 36 litres"},{"k":"p","l":0,"v":"Desired Sodium Increase:"},{"k":"p","l":0,"v":"The target increase in serum sodium = 135 mEq/L - 125 mEq/L = 10 mEq/L"},{"k":"p","l":0,"v":"Sodium Deficit Calculation:"},{"k":"p","l":0,"v":"Sodium deficit = 10 mEq/L × 36 L = 360 mEq"},{"k":"p","l":0,"v":"Safe Increase in Sodium:"},{"k":"b","l":0,"v":"In acute symptomatic hyponatremia with seizures, an initial rapid correction of 4-6 mEq/L in the first few hours is recommended to stabilise neurological symptoms."},{"k":"b","l":0,"v":"The total correction should not exceed 8-12 mEq/L in the first 24 hours to avoid complications such as osmotic demyelination syndrome."}]},{"n":23,"q":"Which among the following statements is false about chronic hyponatremia?","o":[{"t":"Rate of correction should be < 8 mEq/L in the first 24 hours"},{"t":"Osmotic demyelination syndrome typically manifests 24 hours after rapid correction of Na+"},{"t":"Males will require more Na+ correction than females for the same deficit"},{"t":"No treatment is usually required for asymptomatic patients"}],"a":[3],"s":[{"k":"h","l":0,"v":"Correct Answer: D) No treatment is usually required for asymptomatic patients."},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Treatment is required even in asymptomatic patients as chronic hyponatremia for prolonged periods can lead to cognitive decline and gait disturbances, leading to falls. Therefore, safe correction of Na+ is required even in patients without overt symptoms."},{"k":"p","l":0,"v":"Chronic hyponatremia:"},{"k":"p","l":1,"v":"Definition Fall in Na+ levels gradually (>48 hours)"},{"k":"p","l":1,"v":"Aetiology Endocrinal: SIADH, Hypothyroidism"},{"k":"p","l":2,"v":"Organ failure: CKD, Cirrhosis, CHF Drugs: Prolonged thiazide use"},{"k":"p","l":1,"v":"Definition Fall in Na+ levels gradually (>48 hours)"},{"k":"img","v":5640},{"k":"p","l":1,"v":"Pathogenesis"},{"k":"p","l":2,"v":"Extrusion of osmolytes (creatine, glutamate, betaine) takes place over time to maintain the extracellular osmolality of CSF as the brain adapts to hyponatremia. Minor outflow of positive ions - Na+/K+ occurs along with water. Cerebral oedema is usually absent /less predominant."},{"k":"p","l":1,"v":"Clinical features Headache, nausea, vomiting, dizziness"},{"k":"p","l":2,"v":"Less severe symptoms are seen. CNS manifestations: Cognitive and gait disturbances."},{"k":"p","l":1,"v":"Treatment Correction of Na+ must be slow and gradual, as rapid"},{"k":"p","l":2,"v":"correction can lead to Osmotic demyelination syndrome. 3% Hypertonic saline infusion at 6-8 mEq/L in the first 24 hours and 6 mEq/L after 24 hours. (Option A) The rate of correction of sodium should not exceed 8mEq/L for any 24 hrs Water deprivation was earlier done, though aiding in the correction of hyponatremia is not feasible in most cases."},{"k":"p","l":1,"v":"Na+ deficit calculation Na+ deficit = TBW x (140 - [Na+])"},{"k":"p","l":2,"v":"TBW (males) = 0.6 x Body weight (in kgs) (Option C) TBW (females) = 0.5 x Body weight (in kgs)"},{"k":"p","l":1,"v":"Osmotic demyelination Predominantly affects Pons, also called Central pontine syndrome myelinolysis."},{"k":"p","l":2,"v":"Clinically manifests 24 hours following rapid sodium correction. (Option B) Clinical features: Quadriplegia, dysarthria, dysphagia, altered mental status Prevention: Addition of DDAVP (Arginine Vasopressin) while initiating sodium correction."}]},{"n":24,"q":"A 30-year-old female post myomectomy was kept in post-op observation when she developed a headache and vomiting, and, 24 hours later, she developed two episodes of seizures. The clinician suspected Hyponatremia and decided to initiate sodium correction. What is the most appropriate management for this patient?","o":[{"t":"3% normal saline 100 ml bolus over 10 mins"},{"t":"3% normal saline infusion at 0.5mEq/hr for 24 hours"},{"t":"5% Dextrose bolus followed by Normal saline infusion"},{"t":"5% Dextrose infusion only"}],"a":[0],"s":[{"k":"h","l":0,"v":"Correct Answer: A) 3% normal saline 100 ml over 10 mins"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Post-gynaecological procedures in a premenopausal female, there is a risk of developing Hyponatremia. Seizure onset within 48 hours of symptoms onset is suggestive of Acute hyponatremia."},{"k":"p","l":0,"v":"Acute hyponatremia:"},{"k":"p","l":1,"v":"Definition Fall in Na+ levels typically < 125 mEq/L, leading to"},{"k":"p","l":2,"v":"cerebral oedema within 48 hours of onset"},{"k":"p","l":1,"v":"Aetiology Acute hyponatremia\" data-author=\"Giuliani, Corinna &"},{"k":"p","l":2,"v":"Peri, Alessandro. (2015). Effects of Hyponatremia on the Brain. Journal of clinical medicine. 3. 1163-77. 10.3390/jcm3041163. \" data-hash=\"8527\" data-license=\"CC BY 4.0\" data-source=\"https://www.rese archgate.net/figure/Effects-of-hyponatremia-on-the-brain- and-adaptive-mechanism-a-Normonatremia-brain_fig1_2 81846604\" data-tags=\"\" src=\"https://image.prepladder.co m/notes/9dAV2AtWSaauIgNIuer71744289325.png\" />"},{"k":"p","l":2,"v":"Iatrogenic: postoperative premenopausal women, correction with hypotonic fluids, colonoscopy preparation Drugs: Thiazide , MDMA (Ecstasy) Abuse Exercise- induced: seen in athletes in vigorous activity"},{"k":"p","l":1,"v":"Pathogenesi Due to rapid deterioration in serum Na+ levels, brain cell s adaptation does not take place."},{"k":"p","l":2,"v":"Intrusion of water leads to cerebral edema, which usually develops within 24-48 hours following rapid fall of Na+."},{"k":"p","l":1,"v":"Clinical Headache, nausea, vomiting, dizziness features Severe symptoms: seizures, altered level of"},{"k":"p","l":2,"v":"consciousness, coma."},{"k":"p","l":1,"v":"Treatment 3% Hypertonic saline 100 ml bolus over 10 mins (1-2"},{"k":"p","l":2,"v":"mEq/L rise is usually seen). (Option A) Repeat serum Na+ levels and clinically assess the patient, and repeat bolus if necessary. Increase serum sodium by 4-6 mEq/L/hr. Slow correction (infusion) is not recommended in Acute Hyponatremia. (Option B)"},{"k":"p","l":0,"v":"5% Dextrose bolus followed by Normal saline infusion (Option C) & 5% Dextrose infusion only (Option D): Correction with Isotonic fluids like Dextrose will shift the Na+ back into the cell and is never recommended in correction of Hyponatremia. Rather, Dextrose is used to correct hypernatremia cases."}]},{"n":25,"q":"A 40-year-old female presented with complaints of lower back pain for 6 months. Her Hb count was low, and a peripheral blood smear revealed normocytic normochromic anaemia. No other abnormalities were found on the preliminary evaluation. Her renal and liver function tests were within normal limits. Bone marrow biopsy is as shown below. What is the most likely electrolyte imbalance seen in this patient?","o":[{"t":"Hypotonic hyponatremia"},{"t":"Isotonic hyponatremia"},{"t":"Hypertonic hyponatremia"},{"t":"Hypernatremia"}],"a":[1],"s":[{"k":"p","l":0,"v":"Correct answer: B) Isotonic hyponatremia"},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"Lower backache (spine pathology), normocytic normochromic anaemia with bone marrow biopsy showing Mott cells (plasma cells with spherical inclusion within the cytoplasm) is suggestive of Multiple myeloma."},{"k":"b","l":0,"v":"Multiple myeloma is a condition associated with Hypergammaglobulinemia (excess paraproteins) - which can lead to Isotonic hyponatremia ."},{"k":"b","l":0,"v":"Renal and liver function within normal limits indicates no liver/renal failure, and other options are ruled out."},{"k":"b","l":0,"v":"Isotonic hyponatremia is sometimes called Pseudohyponatremia , as low Na+ levels are due to hindering factors that interfere with techniques used for Na+ measurement techniques."},{"k":"p","l":0,"v":"Causes of Isotonic Hyponatremia:"},{"k":"b","l":0,"v":"Hyperproteinemia/Hypergammaglobulinemia : as seen in Multiple myeloma."},{"k":"b","l":0,"v":"Hyperlipidemia: especially in patients with severe hypertriglyceridemia."},{"k":"b","l":0,"v":"Graft vs Host disease"},{"k":"b","l":0,"v":"Infusion of isotonic glycine/ mannitol in urology/gynaecology procedures"},{"k":"p","l":0,"v":"Causes of Hyponatremia:"},{"k":"p","l":0,"v":"Hypotonic hyponatre Isotonic hyponatremia Hypertonic hyponatre mia mia"},{"k":"p","l":0,"v":"Hypovolemic Diarrhea/vomiting Multiple myeloma Exogenous infusion of"},{"k":"p","l":2,"v":"Enterocutaneous fistula Hyperlipidemia Mannitol/glycine Cerebral salt wasting Graft vs Host disease Radiocontrast dyes syndrome Hyperglycemic"},{"k":"p","l":2,"v":"hyperosmolar state (HHS)"},{"k":"p","l":0,"v":"Euvolemic SIADH"},{"k":"p","l":2,"v":"Hypothyroidism Secondary hyperaldostero nism"},{"k":"p","l":0,"v":"Hypervolemic AKI/CKD"},{"k":"p","l":2,"v":"CHF Cirrhosis Nephrotic syndrome"},{"k":"img","v":5649}],"qi":[5604]},{"n":26,"q":"Values of serum Sodium and plasma Osmolality are, Na+: 130 mEq/L Osmolality: 310 mOsm/L Which among the following clinical scenarios is least likely to cause this derangement?","o":[{"t":"A 60-year male with blood glucose > 500 mg/dL upon arrival"},{"t":"Patient developing headache and dizziness post-MRI with contrast"},{"t":"Exogenous infusion of mannitol to a patient with a head injury"},{"t":"A 40 year female excreting > 20 L urine per day with absence of pituitary bright spot on MRI"}],"a":[3],"s":[{"k":"h","l":0,"v":"Correct Answer: D) A 40 year female excreting > 20 L urine per day with absence of pituitary bright spot on MRI"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"A 40-year female excreting > 20 L urine per day with the absence of a pituitary bright spot on MRI is suggestive of Central Diabetes insipidus (DI) , where there is a deficiency of ADH (Vasopressin) leading to dilute polyuria (>20L) with increased serum osmolality and increased serum sodium levels - Hypertonic Hypernatremia ."},{"k":"p","l":0,"v":"Serum sodium is low (N: 135-145 mEq/L), and plasma osmolality is elevated (N: <295 mOsm/L) - indicating Hypertonic hyponatremia ."},{"k":"b","l":0,"v":"Hypertonic hyponatremia occurs when osmotically active molecules ( increased glucose, mannitol, or iodinated dyes) in serum or ECF cause water to shift from intracellular to extracellular space."},{"k":"b","l":0,"v":"This results in a decrease in plasma sodium concentration even though total body sodium is normal."},{"k":"p","l":0,"v":"Causes of Hypertonic hyponatremia:"},{"k":"b","l":0,"v":"Hyperglycemic hyperosmolar syndrome (HHS): seen in T2DM, blood glucose > 500-600 mg/dL (Option A)"},{"k":"b","l":0,"v":"Radiocontrast dyes (Option B)"},{"k":"b","l":0,"v":"Mannitol /glycine infusion (Option C)"}]},{"n":27,"q":"A patient admitted to ICU developed symptoms of headache, nausea, vomiting, and sudden onset seizures. On examination, the patient has bilateral pedal oedema. The Intensivist suspected an electrolyte abnormality and sent for serum and urine analysis (given below). What could be the likely cause leading to the patient's symptoms? Na+: 124 mEq/L, K+: 4.8 mEq/L, Cl-: 90 mEq/L, Urinary Na+: 25 mM.","o":[{"t":"Acute kidney injury"},{"t":"Nephrotic syndrome"},{"t":"Liver failure"},{"t":"Congestive heart failure"}],"a":[0],"s":[{"k":"p","l":0,"v":"Correct answer: A) Acute kidney injury"},{"k":"h","l":0,"v":"Explanation:"},{"k":"b","l":0,"v":"The clinical scenario is suggestive of Hypervolemic hyponatremia with Urinary Na+ > 20 mM, which is most likely secondary to Acute kidney injury (AKI)."},{"k":"b","l":0,"v":"Pedal oedema is seen in hypervolemic states and not in euvolemic/ hypovolemic conditions."},{"k":"p","l":0,"v":"Electrolyte normal values:"},{"k":"p","l":1,"v":"Na+ 135-145 mEq/L"},{"k":"p","l":1,"v":"K+ 3.5-5 mEq/L"},{"k":"p","l":1,"v":"Cl- 98-106 mEq/L"},{"k":"p","l":0,"v":"Hypervolemic hyponatremia:"},{"k":"p","l":1,"v":"Primary defect TBW ››; TBS › (But sodium (Hypotonic state) concentration fl)"},{"k":"p","l":2,"v":"(TBW- Total body water, TBS- Total body sodium)"},{"k":"p","l":1,"v":"Pathogenesis Hyperaldosteronism secondary to"},{"k":"p","l":2,"v":"massive ascites - leading to increased activity of ENaC channels fi Water retention ›› (in comparison to salt retention)."},{"k":"p","l":1,"v":"Causes U.Na+ > 20 mM U.Na+ <"},{"k":"p","l":2,"v":"20 mM"},{"k":"p","l":1,"v":"Acute kidney injury Ascites: (AKI) CHF Chronic kidney Cirrhosis (Liver failure) disease (CKD) Nephrotic syndrome"}]},{"n":28,"q":"A 49-year-old lady with hypothyroidism is presenting with nausea and headache. Her serum sodium level is 126 mmol/L. What kind of hyponatremia is this most likely to be?","o":[{"t":"Hypovolemic hyponatremia"},{"t":"Hypervolemic hyponatremia"},{"t":"Euvolemic hyponatremia"},{"t":"None of the above"}],"a":[2],"s":[{"k":"h","l":0,"v":"Correct Answer: C) Euvolemic hyponatremia"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Hypothyroidism causes euvolemic hyponatremia."},{"k":"p","l":0,"v":"Euvolemic Hyponatremia - TBW- total body water increase with stable total body sodium"},{"k":"p","l":0,"v":"Causes of euvolemic hyponatremia include:"},{"k":"b","l":0,"v":"Drugs (desmopressin, oxytocin, antidepressants, opioids, thiazide diuretics, carbamazepine or its analogues, vincristine , nicotine, antipsychotics, chlorpropamide, cyclophosphamide , nonsteroidal anti-inflammatory drugs, MDMA)"},{"k":"b","l":0,"v":"Syndrome of inappropriate antidiuretic hormone (SIADH)"},{"k":"b","l":0,"v":"Addison's disease"},{"k":"b","l":0,"v":"Hypothyroidism"},{"k":"b","l":0,"v":"High fluid intake in conditions like primary polydipsia or potomania, caused by a low intake of solutes with relatively high fluid intake"},{"k":"b","l":0,"v":"Medical testing related to excessive fluids, such as a colonoscopy or cardiac catheterisation"},{"k":"b","l":0,"v":"Iatrogenic"}]},{"n":29,"q":"SIADH is an example of what kind of hyponatremia?","o":[{"t":"Hypovolemic hyponatremia"},{"t":"Hypervolemic hyponatremia"},{"t":"Euvolemic hyponatremia"},{"t":"Any of the above"}],"a":[2],"s":[{"k":"h","l":0,"v":"Correct Answer: C) Euvolemic hyponatremia"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"SIADH is an example of euvolemic hyponatremia ."},{"k":"p","l":0,"v":"SIADH (Syndrome of inappropriate antidiuretic hormone secretion):"},{"k":"b","l":0,"v":"Increased ADH leads to water retention with near-normal sodium levels."},{"k":"b","l":0,"v":"Water overload leads to the release of ANP ( Atrial natriuretic peptide) from atria."},{"k":"b","l":0,"v":"ANP causes natriuresis which leads to euvolemic hyponatremia."},{"k":"b","l":0,"v":"No edema occurs."},{"k":"img","v":5657},{"k":"img","v":5659},{"k":"p","l":0,"v":"Causes of SIADH:"},{"k":"b","l":0,"v":"Tumours"},{"k":"b","l":0,"v":"Central nervous system disorders: stroke, trauma, infection, psychosis, porphyria"},{"k":"b","l":0,"v":"Pulmonary disorders: pneumonia, tuberculosis, obstructive lung disease"},{"k":"b","l":0,"v":"Drugs: anticonvulsants, psychotropics, antidepressants, cytotoxics, oral hypoglycaemic agents, opiates"},{"k":"b","l":0,"v":"Idiopathic"}]},{"n":30,"q":"A 50-year-old female is presenting with nausea, delirium, and headache. She has had loose stools for the past 2 days. What is the diagnosis?","o":[{"t":"Hypovolemic hyponatremia"},{"t":"Hypervolemic hypernatremia"},{"t":"Hypovolemic hypernatremia"},{"t":"Euvolemic hyponatremia"}],"a":[0],"s":[{"k":"h","l":0,"v":"Correct Answer: A) Hypovolemic hyponatremia"},{"k":"h","l":0,"v":"Explanation:"},{"k":"p","l":0,"v":"Gastrointestinal fluid loss by diarrhoea or vomiting is an example of hypovolemic hyponatremia."},{"k":"p","l":0,"v":"Hypovolemic hyponatremia is a condition where the body loses more sodium than water, decreasing total body water and sodium."},{"k":"b","l":0,"v":"This causes a decrease in blood volume and serum osmolality, which triggers the release of vasopressin (antidiuretic hormone, or ADH) to maintain blood volume."},{"k":"b","l":0,"v":"The resulting water retention dilutes the plasma, leading to hyponatremia."},{"k":"p","l":0,"v":"Causes of Hypovolemic Hyponatremia"},{"k":"b","l":0,"v":"Gastrointestinal fluid loss ( diarrhoea or vomiting)"},{"k":"b","l":0,"v":"The third spacing of fluids (pancreatitis, hypoalbuminemia, small bowel obstruction)"},{"k":"b","l":0,"v":"Diuretics"},{"k":"b","l":0,"v":"Osmotic diuresis (glucose, mannitol)"},{"k":"b","l":0,"v":"Salt-wasting nephropathies"},{"k":"b","l":0,"v":"Cerebral salt-wasting syndrome (urinary salt wasting, possibly caused by increased brain natriuretic peptide)"},{"k":"b","l":0,"v":"Mineralocorticoid deficiency"},{"k":"img","v":5649}]}]);
QB.imgs({"5632":"data:image/jpeg;base64,","5604":"data:image/jpeg;base64,","5640":"data:image/jpeg;base64,","5649":"data:image/jpeg;base64,","5620":"data:image/jpeg;base64,","5588":"data:image/jpeg;base64,","5591":"data:image/jpeg;base64,","5657":"data:image/jpeg;base64,","5659":"data:image/jpeg;base64,","5599":"data:image/jpeg;base64,"});